// Key attributes by key id (0..52).
//   start/width - in 8-pixel half-units across the 256-pixel panel
//   nchars, c0..c4 - label; sh - shifted label (1 char), has_sh valid
//   mrow/mcol - Dragon matrix position; is_shift - SHIFT latch key
//   prow - panel row (0..4) the key sits on
module osd_key_table (
    input  wire [5:0] id,
    output reg  [4:0] start,
    output reg  [4:0] width,
    output reg  [2:0] nchars,
    output reg  [5:0] c0, c1, c2, c3, c4,
