// First key id and key count of each panel row.
module osd_row_info (
    input  wire [2:0] prow,
    output reg  [5:0] first,
    output reg  [5:0] count
);
    always_comb begin
        case (prow)
            3'd0: begin first = 6'd0; count = 6'd13; end
            3'd1: begin first = 6'd13; count = 6'd14; end
            3'd2: begin first = 6'd27; count = 6'd13; end
            3'd3: begin first = 6'd40; count = 6'd12; end
            3'd4: begin first = 6'd52; count = 6'd1; end
            default: begin first = 6'd0; count = 6'd1; end
        endcase
    end
endmodule

`default_nettype wire
